CREATE TABLE core.business_preferences(company_id uuid PRIMARY KEY REFERENCES core.companies(id),sales_terms_days int NOT NULL DEFAULT 30 CHECK(sales_terms_days BETWEEN 0 AND 365),purchase_terms_days int NOT NULL DEFAULT 30 CHECK(purchase_terms_days BETWEEN 0 AND 365),quote_valid_days int NOT NULL DEFAULT 30 CHECK(quote_valid_days BETWEEN 1 AND 365),default_dispatch_mode text NOT NULL DEFAULT 'PICKUP' CHECK(default_dispatch_mode IN('PICKUP','DELIVERY')),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog.unit_barcodes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),product_unit_id uuid NOT NULL,barcode text NOT NULL CHECK(length(barcode) BETWEEN 1 AND 80 AND barcode=btrim(barcode) AND barcode !~* '^(BIN|LOT):'),active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES identity.users(id),created_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,barcode),FOREIGN KEY(company_id,product_unit_id) REFERENCES catalog.product_units(company_id,id));
DO $$ DECLARE sc text;tb text;BEGIN FOR sc,tb IN SELECT * FROM(VALUES('core','business_preferences'),('catalog','unit_barcodes'))v(s,t)LOOP EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY',sc,tb);EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY',sc,tb);EXECUTE format('CREATE POLICY company_scope ON %I.%I USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company())',sc,tb);EXECUTE format('CREATE TRIGGER touch_version BEFORE UPDATE ON %I.%I FOR EACH ROW EXECUTE FUNCTION core.touch_version()',sc,tb);END LOOP;END $$;
INSERT INTO identity.permissions(code,description) VALUES('settings.business.read','Read business defaults and numbering'),('settings.business.write','Maintain prospective business defaults and numbering');
CREATE FUNCTION identity.seed_business_preferences(c uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 INSERT INTO core.business_preferences(company_id) VALUES(c) ON CONFLICT DO NOTHING;
 INSERT INTO identity.role_permissions(company_id,role_id,permission_code) SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','FINANCE','OFFICE','PROCUREMENT') AND p.code='settings.business.read') OR(r.code IN('ADMIN','FINANCE') AND p.code='settings.business.write')) ON CONFLICT DO NOTHING;END $$;
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_business_preferences(c);END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION core.configure_business(expected bigint,sales_days int,purchase_days int,quote_days int,dispatch text,p_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 PERFORM purchase.require_access('settings.business.write');IF expected IS NULL OR sales_days IS NULL OR purchase_days IS NULL OR quote_days IS NULL OR dispatch IS NULL OR p_notes IS NULL THEN RAISE EXCEPTION 'Explicit business defaults required' USING ERRCODE='HS422';END IF;
 PERFORM 1 FROM core.business_preferences WHERE company_id=core.current_company() AND version=expected FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Settings changed' USING ERRCODE='HS409';END IF;
 UPDATE core.business_preferences SET sales_terms_days=sales_days,purchase_terms_days=purchase_days,quote_valid_days=quote_days,default_dispatch_mode=dispatch,notes=p_notes WHERE company_id=core.current_company();END $$;
CREATE FUNCTION core.configure_numbering(typ text,expected bigint,p_prefix text,p_next bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE row platform.document_sequences;candidate text;BEGIN
 PERFORM purchase.require_access('settings.business.write');IF p_prefix IS NULL OR p_prefix !~ '^[A-Z0-9][A-Z0-9_-]{0,19}$' OR p_next IS NULL OR p_next<1 OR p_next>999999999999 THEN RAISE EXCEPTION 'Invalid numbering prefix or next value' USING ERRCODE='HS422';END IF;
 SELECT * INTO row FROM platform.document_sequences WHERE company_id=core.current_company() AND document_type=typ FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Sequence unavailable' USING ERRCODE='HT404';END IF;
 IF row.version<>expected OR p_next<row.next_value THEN RAISE EXCEPTION 'Sequence changed or counter cannot rewind' USING ERRCODE='HS409';END IF;candidate:=p_prefix||lpad(p_next::text,greatest(6,length(p_next::text)),'0');IF EXISTS(SELECT 1 FROM platform.documents WHERE company_id=row.company_id AND document_type=typ AND number=candidate) THEN RAISE EXCEPTION 'Number already used' USING ERRCODE='HS409';END IF;
 UPDATE platform.document_sequences SET prefix=p_prefix,next_value=p_next WHERE company_id=row.company_id AND id=row.id;END $$;
REVOKE ALL ON FUNCTION identity.seed_business_preferences(uuid),core.configure_business(bigint,int,int,int,text,text),core.configure_numbering(text,bigint,text,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION core.configure_business(bigint,int,int,int,text,text),core.configure_numbering(text,bigint,text,bigint) TO htt_app;
GRANT SELECT ON core.business_preferences,catalog.unit_barcodes TO htt_app;GRANT INSERT,UPDATE ON catalog.unit_barcodes TO htt_app;
CREATE FUNCTION catalog.guard_barcode_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE prod uuid;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text||':'||NEW.barcode,0));
 IF TG_TABLE_NAME='unit_barcodes' THEN SELECT product_id INTO prod FROM catalog.product_units WHERE company_id=NEW.company_id AND id=NEW.product_unit_id;
 IF EXISTS(SELECT 1 FROM catalog.product_barcodes WHERE company_id=NEW.company_id AND barcode=NEW.barcode AND product_id<>prod) THEN RAISE EXCEPTION 'Barcode assigned to another product' USING ERRCODE='23505';END IF;
 ELSE IF EXISTS(SELECT 1 FROM catalog.unit_barcodes b JOIN catalog.product_units u ON u.company_id=b.company_id AND u.id=b.product_unit_id WHERE b.company_id=NEW.company_id AND b.barcode=NEW.barcode AND u.product_id<>NEW.product_id) THEN RAISE EXCEPTION 'Barcode assigned to another product unit' USING ERRCODE='23505';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER barcode_owner BEFORE INSERT OR UPDATE ON catalog.unit_barcodes FOR EACH ROW EXECUTE FUNCTION catalog.guard_barcode_owner();
CREATE TRIGGER barcode_owner BEFORE INSERT OR UPDATE ON catalog.product_barcodes FOR EACH ROW EXECUTE FUNCTION catalog.guard_barcode_owner();
REVOKE ALL ON FUNCTION catalog.guard_barcode_owner() FROM PUBLIC;

-- Staff search reuses publication barcodes under the existing company RLS policy.
GRANT SELECT ON catalog.product_barcodes TO htt_app;
